from __future__ import annotations

import json
import os
import re
from pathlib import Path, PureWindowsPath
from typing import Any
from uuid import uuid4

from rq1.autopilot.models import RunPlan, canonical_hash
from rq1.utils.time import utc_now


_RUN_ID = re.compile(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\Z")


def validate_run_id(run_id: str) -> str:
    """Accept only canonical UUID run IDs generated by the autopilot."""
    if not isinstance(run_id, str) or not _RUN_ID.fullmatch(run_id):
        raise ValueError("Invalid autopilot run ID; expected a canonical lowercase UUID")
    return run_id


def validate_output_directory(root: Path, output_directory: str) -> str:
    """Require a root-relative output path whose existing components are not symlinks."""
    if not isinstance(output_directory, str) or not output_directory.strip():
        raise ValueError("Autopilot output_directory must be a non-empty root-relative path")
    # Interpret both separator styles consistently on Windows and Linux/WSL.
    normalized = output_directory.replace("\\", "/")
    windows_path = PureWindowsPath(output_directory)
    candidate = Path(normalized)
    if candidate.is_absolute() or windows_path.is_absolute() or windows_path.drive:
        raise ValueError("Autopilot output_directory must be root-relative")
    parts = candidate.parts
    if not parts or any(part in {"", ".", ".."} for part in parts):
        raise ValueError("Autopilot output_directory cannot contain empty, '.' or '..' components")

    root_resolved = root.resolve()
    cursor = root_resolved
    for part in parts:
        cursor = cursor / part
        if cursor.is_symlink():
            raise ValueError("Autopilot output_directory cannot traverse symlink components")
    resolved = cursor.resolve(strict=False)
    if not resolved.is_relative_to(root_resolved):
        raise ValueError("Autopilot output_directory escapes the repository root")
    return Path(*parts).as_posix()


def _run_directory(root: Path, run_id: str) -> Path:
    validate_run_id(run_id)
    trusted_root = root.resolve()
    cursor = trusted_root
    for part in ("artifacts", "autopilot", run_id):
        cursor = cursor / part
        if cursor.is_symlink():
            raise ValueError("Autopilot state paths cannot traverse symlinks")
    base = trusted_root / "artifacts" / "autopilot"
    directory = base / run_id
    resolved_base = base.resolve(strict=False)
    resolved_directory = directory.resolve(strict=False)
    if not resolved_base.is_relative_to(trusted_root) or resolved_directory.parent != resolved_base:
        raise ValueError("Autopilot run path escapes the approved state directory")
    return directory


def run_dir(root: Path, run_id: str) -> Path:
    return _run_directory(root, run_id)


def state_path(root: Path, run_id: str) -> Path:
    path = _run_directory(root, run_id) / "state.json"
    if path.is_symlink():
        raise ValueError("Autopilot state file cannot be a symlink")
    return path


def contingency_path(root: Path, run_id: str) -> Path:
    path = _run_directory(root, run_id) / "contingencies.jsonl"
    if path.is_symlink():
        raise ValueError("Autopilot contingency log cannot be a symlink")
    return path


def write_atomic(path: Path, payload: dict[str, Any], *, overwrite: bool = True) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    # Use a unique exclusive-create temporary file so a pre-planted .tmp symlink
    # cannot redirect writes outside the already validated directory.
    temp = path.with_name(f".{path.name}.{uuid4().hex}.tmp")
    try:
        with temp.open("x", encoding="utf-8") as handle:
            handle.write(json.dumps(payload, indent=2, sort_keys=True) + "\n")
            handle.flush()
            os.fsync(handle.fileno())
        if overwrite:
            os.replace(temp, path)
        else:
            # A same-directory hardlink publishes the complete file atomically
            # while refusing to replace a concurrently created destination.
            os.link(temp, path)
            temp.unlink()
    except BaseException:
        temp.unlink(missing_ok=True)
        raise


def _stored_plan_hash_is_valid(plan: dict[str, Any], outer_hash: Any) -> bool:
    full_hash = canonical_hash({key: value for key, value in plan.items() if key != "content_hash"})
    if plan.get("content_hash") == full_hash and outer_hash == full_hash:
        return True

    # Earlier releases hashed only the five explicit plan fields. Accept those
    # genuine records only when every omitted field still equals its RunPlan default.
    legacy_keys = ("schema_version", "run_plan_id", "mode", "repository_commit", "output_directory")
    if not all(key in plan for key in legacy_keys):
        return False
    try:
        baseline = RunPlan(
            schema_version=plan["schema_version"],
            run_plan_id=plan["run_plan_id"],
            mode=plan["mode"],
            repository_commit=plan["repository_commit"],
            output_directory=plan["output_directory"],
        ).to_dict()
    except (TypeError, ValueError):
        return False
    baseline = json.loads(json.dumps(baseline))
    if set(plan) != set(baseline):
        return False
    for key, expected in baseline.items():
        if key not in {*legacy_keys, "content_hash"} and plan.get(key) != expected:
            return False
    legacy_hash = canonical_hash({key: plan[key] for key in legacy_keys})
    return plan.get("content_hash") == legacy_hash and outer_hash == legacy_hash


def load(root: Path, run_id: str) -> dict[str, Any]:
    value = json.loads(state_path(root, run_id).read_text(encoding="utf-8"))
    if value.get("run_id") != run_id:
        raise ValueError("Autopilot state run ID does not match its requested directory")
    plan = value.get("plan")
    if not isinstance(plan, dict) or plan.get("run_plan_id") != run_id:
        raise ValueError("Autopilot stored plan run ID does not match its state directory")
    validate_output_directory(root, plan.get("output_directory"))
    if not _stored_plan_hash_is_valid(plan, value.get("plan_hash")):
        raise ValueError("Autopilot stored plan hash is invalid")
    return value


def initialize(root: Path, run_id: str, plan: dict[str, Any], stages: list[str]) -> dict[str, Any]:
    validate_run_id(run_id)
    if plan.get("run_plan_id") != run_id:
        raise ValueError("Autopilot plan run ID does not match the requested state directory")
    validate_output_directory(root, plan.get("output_directory"))
    path = state_path(root, run_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    # Recheck after directory creation to catch a symlink substituted during setup.
    path = state_path(root, run_id)
    if path.exists():
        raise FileExistsError(f"Autopilot state already exists for run {run_id}")
    value = {
        "schema_version": 1,
        "run_id": run_id,
        "created_at": utc_now(),
        "plan": plan,
        "plan_hash": plan["content_hash"],
        "top_status": "RUNNING",
        "stop_requested": False,
        "last_successful_stage": None,
        "heartbeat": None,
        "stages": {name: {"status": "pending", "attempts": []} for name in stages},
    }
    write_atomic(path, value, overwrite=False)
    return value


def heartbeat(root: Path, state: dict[str, Any]) -> None:
    run_id = validate_run_id(state.get("run_id"))
    state_path_value = state_path(root, run_id)
    if not state_path_value.is_file():
        raise FileNotFoundError(f"Autopilot state does not exist for run {run_id}")
    state["heartbeat"] = utc_now()
    write_atomic(state_path_value, state)


def append_contingency(root: Path, run_id: str, payload: dict[str, Any]) -> None:
    path = contingency_path(root, run_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    # O_NOFOLLOW prevents following a symlink if one is raced in after the check
    # on platforms that provide it. The path is revalidated immediately before open.
    path = contingency_path(root, run_id)
    flags = os.O_WRONLY | os.O_CREAT | os.O_APPEND
    flags |= getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(path, flags, 0o600)
    with os.fdopen(descriptor, "a", encoding="utf-8") as handle:
        handle.write(json.dumps(payload, sort_keys=True) + "\n")
